                                offer_adjustment(i, p['floor'], day.isoformat(), 'I cannot record that amount. The rest will remain overdue.', 'floor')
                            complete = False
                            break
                        if amount > p['past_due']:
                            offer_adjustment(i, p['past_due'], day.isoformat(), 'The full past-due amount is ' + money(p['past_due']) + '.', 'amount')
                            complete = False
                            break
                        p['amount'] = amount
                        p['date'] = day.isoformat()
                        p['status'] = 'pending'
                        p['awaiting_date'] = False
                        if amount < p['past_due']:
                            prefix += 'The rest will remain overdue. '
                    if complete:
                        progress()
                elif kind == 'too_much':
                    i = indices[0]
                    p = s['products'][i]
                    p['too_much'] = True
                    if p['floor_offered']:
                        reject(i)
                    else:
                        p['floor_offered'] = True
                        day = p.get('offered_date') or (today.isoformat() if business(today) else following(today).isoformat())
                        offer_adjustment(i, p['floor'], day, 'The rest will remain overdue.', 'floor')
                elif yes == 'yes' and s['phase'] != 'confirm':
                    for i in indices:
                        p = s['products'][i]
                        if p['status'] != 'open':
                            continue
                        day = p.get('offered_date') or today.isoformat()
                        d = datetime.date.fromisoformat(day)
                        if not business(d):
                            d = following(d)
                            prefix += 'The next business day is ' + spoken(d) + '. '
                        p['amount'] = p.get('offered_amount', p['past_due'])
                        p['date'] = d.isoformat()
                        p['status'] = 'pending'
                    progress()
                elif s['phase'] == 'confirm' and kind in ['refusal', 'nonanswer'] or s['phase'] == 'confirm' and yes == 'no':
                    for p in s['products']:
                        if p['status'] == 'pending':
                            p['status'] = 'open'
                    progress()
                elif kind in ['refusal', 'nonanswer'] or yes == 'no':
                    i = indices[0]
                    p = s['products'][i]
                    if p.get('awaiting_date'):
                        p['date_clarifications'] += 1
                        p['awaiting_date'] = False
                        offer_adjustment(i, p['amount'], p['deadline'], 'I can offer the latest permitted date.', 'deadline')
                    elif s['mode'] == 'all':
                        progress()
                    else:
                        reject(i)
                elif not prefix:
                    s['say'] = s['say'] or 'Please tell me whether you accept the proposed payment.'
    if s['phase'] == 'verifying':
        if s['verify_field'] == 'phone_last4' and not s['dob_ok']:
            raise ValueError('security order')
        vars['security_field'] = s['verify_field']
        vars['security_answer'] = s['verify_answer']
        vars['engine_route'] = 'verify'
    elif s['phase'] == 'loading':
        if not (s['verified'] and s['dob_ok'] and s['phone_ok']):
            raise ValueError('lookup gate')
        vars['engine_route'] = 'lookup'
    elif s['phase'] in ['collect', 'confirm', 'hardship', 'recording']:
        if not (s['verified'] and s['loaded']):
            raise ValueError('collection gate')
        if s['phase'] == 'recording':
            pending = [p for p in s['products'] if p['status'] == 'pending']
            if pending:
                if not s['confirmed']:
                    raise ValueError('confirmation gate')
                p = pending[0]
                d = datetime.date.fromisoformat(p['date'])
                if not (p['floor'] <= p['amount'] <= p['past_due'] and today <= d <= datetime.date.fromisoformat(p['deadline']) and business(d) and p['write_attempts'] < 2):
                    raise ValueError('write gate')
                vars['write_request'] = json.dumps(dict(product_id=p['product_id'], amount=p['amount'], date=p['date']))
                vars['engine_route'] = 'record'
            else:
                s['phase'] = 'final'
        else:
            vars['engine_route'] = 'collect'
            vars['collection_instruction'] = prefix + s['say']
    if s['phase'] in ['final', 'resolve']:
        if s['transferred']:
            s['close_outcome'] = 'transferred'
            s['close_reason'] = 'human' if s['transferred'] == 'general' else s['transferred']
            s['action'] = ''
        if s['action'] in ['schedule_callback', 'transfer_to_agent']:
            vars['engine_route'] = 'resolve'
            vars['resolution_action'] = s['action']
            request = s.get('callback_request', dict()) if s['action'] == 'schedule_callback' else dict(queue=s.get('transfer_request', ''))
            vars['resolution_instruction'] = 'Immediately call ' + s['action'] + ' with this approved request: ' + json.dumps(request) + '. Do not claim success before the bank confirms it.'
        elif s['loaded'] and not s['transferred'] and not s['close_outcome']:
            if not s['verified']:
                raise ValueError('note gate')
            if any(p['status'] in ['open', 'pending', 'abandoned'] for p in s['products']):
                raise ValueError('unfinished products')
            missing = [p for p in s['products'] if p['status'] != 'recorded' and not p['noted']]
            if missing:
                p = missing[0]
                if p['reason'] not in ['refused', 'hardship', 'dispute', 'paid', 'service_error']:
                    raise ValueError('note reason')
                s['note_request'] = dict(product_id=p['product_id'], reason=p['reason'])
                vars['engine_route'] = 'resolve'
                vars['resolution_action'] = 'add_note'
                vars['resolution_instruction'] = 'Final non-transfer resolution. Immediately call add_note with ' + json.dumps(s['note_request']) + '. Ask no further customer question. Do not announce that a failed write succeeded.'
            else:
                recorded = [p for p in s['products'] if p['status'] == 'recorded']
                if recorded:
                    s['close_outcome'] = 'promise'
                    s['close_reason'] = ''
                else:
                    nonpaid = [p for p in s['products'] if p['reason'] != 'paid']
                    s['close_outcome'] = 'no_promise' if nonpaid else 'paid'
                    s['close_reason'] = nonpaid[0]['reason'] if nonpaid else ''
        if s['close_outcome'] and not s['action']:
            vars['engine_route'] = 'closing'
            messages = list(s['notice'])
            if any(p['status'] == 'recorded' for p in s['products']):
                messages.append('You will receive a text message confirming this promise.')
            vars['closing_instruction'] = ' '.join(messages + ['Thank you for your time. Goodbye.'])
    if vars['engine_route'] == 'identity':
        if s['phase'] == 'dob' and not s['say']:
            s['say'] = 'What is your date of birth?'
        elif s['phase'] == 'phone' and not s['say']:
            s['say'] = 'What are the last four digits of the phone number on file?'
        elif s['phase'] == 'name' and not s['say']:
            s['say'] = 'Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '?'
        vars['identity_instruction'] = prefix + s['say']
    vars['calendar_facts'] = [dict(product_id=p['product_id'], label=p['label'], floor=p['floor'], deadline=p['deadline'], offer_day=p['offer_day'], band=p['band'], budget=p['budget'], attempts=p['attempts']) for p in s['products']]
    vars['state_json'] = json.dumps(s)
except Exception:
    vars['engine_route'] = 'identity'
    vars['identity_instruction'] = 'I do not have that information available right now. Do not discuss account details, promise a result, or make a bank write.'
    vars['collection_instruction'] = ''
    vars['resolution_instruction'] = ''
    vars['resolution_action'] = ''
    vars['closing_instruction'] = ''
    vars['security_field'] = ''
    vars['security_answer'] = ''
    vars['write_request'] = ''
    vars['calendar_facts'] = []
